     "nombre0": "$s1.0.name", "precio0": "$s1.0.price_clp", "id0": "$s1.0.id",
     "nombre1": "$s1.1.name", "precio1": "$s1.1.price_clp", "id1": "$s1.1.id",
     "nombre2": "$s1.2.name", "precio2": "$s1.2.price_clp", "id2": "$s1.2.id",
